set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
test -z "$(squeue -h --name=cosearch-local-five -o %i)"
base64 -d > "$R/tools/gpu-ranker-k.bundle" <<'BUNDLE'

BUNDLE
cd "$R/repo"
test "$(git rev-parse --short HEAD)" = 7540088
git fetch "$R/tools/gpu-ranker-k.bundle" HEAD
git merge --ff-only FETCH_HEAD
cp reproduction/baselines/agent6-20261002/local_gpu_five.py "$R/tools/five_iteration_job_k.py"
"$R/env/bin/python" -m py_compile reproduction/baselines/agent6-20261002/native_parallel_ranker_probe.py
test ! -d "$R/runs/cosearch-local-gpu-five-20261003-k"
tmux new-session -d -s cosearch-local-gpu-five-k-20261003 "srun --immediate=60 -p gpu -w h100-16 -N1 --ntasks=1 --gres=gpu:h100:8 --exclusive --cpus-per-task=128 --mem=768G --job-name=cosearch-local-five env PYTHONPATH='$R/repo' COSEARCH_RUN_ID=cosearch-local-gpu-five-20261003-k '$R/env/bin/python' -m search_r1.baselines.preflight -- '$R/env/bin/python' '$R/tools/five_iteration_job_k.py' > '$R/logs/local-five-k.log' 2>&1"
sleep 3
squeue -h --name=cosearch-local-five -o '%i %T %N'
